// 启动自动刷新
function startHttpdStatusAutoRefresh() {
    // 先清除现有的定时器
    if (httpdStatusTimer) {
        clearInterval(httpdStatusTimer);
    }

    // 立即执行一次
    getHttpdStatus();

    // 设置定时器，每5秒刷新一次
    httpdStatusTimer = setInterval(getHttpdStatus, 5000);
}

// 停止自动刷新
function stopHttpdStatusAutoRefresh() {
    if (httpdStatusTimer) {
        clearInterval(httpdStatusTimer);
        httpdStatusTimer = null;
    }
}


